\set ON_ERROR_STOP on
begin;
set local search_path=public,extensions;
select no_plan();
-- Nur Testkennungen aus den absichtlich nicht für service_role freigegebenen Entwurfstabellen lesen.
create function pg_temp.draft_id() returns uuid language sql security definer as $$select id from public.listings where workspace_id='51000000-0000-4000-8000-000000000011';$$;
create function pg_temp.image_id() returns uuid language sql security definer as $$select id from public.listing_images where workspace_id='51000000-0000-4000-8000-000000000011';$$;
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values ('51000000-0000-4000-8000-000000000001','authenticated','authenticated','transfer@example.test','{}','{}'),('51000000-0000-4000-8000-000000000002','authenticated','authenticated','outsider@example.test','{}','{}');
insert into public.platform_operators(user_id) values('51000000-0000-4000-8000-000000000001');
insert into public.workspaces(id,name) values('51000000-0000-4000-8000-000000000011','Transfer');
insert into public.workspace_members(workspace_id,user_id,role) values('51000000-0000-4000-8000-000000000011','51000000-0000-4000-8000-000000000001','owner');
insert into public.marketplace_connections(id,workspace_id,display_name,external_account_id,status) values('51000000-0000-4000-8000-000000000021','51000000-0000-4000-8000-000000000011','Vinted','99','connected');
insert into public.marketplace_account_entries(id,workspace_id,connection_id,kind,external_id,body) values('51000000-0000-4000-8000-000000000031','51000000-0000-4000-8000-000000000011','51000000-0000-4000-8000-000000000021','publication','123',jsonb_build_object('transferSource',jsonb_build_object('title','Jacke','description','Vollständiger Text','photoReferences',jsonb_build_array('https://images1.vinted.net/test.jpg'),'externalAccountId','99','observedAt',clock_timestamp())));
insert into public.kleinanzeigen_connections(workspace_id,external_account_id,display_name,account_type,created_by) values('51000000-0000-4000-8000-000000000011','88','Kleinanzeigen','private','51000000-0000-4000-8000-000000000001');
create function pg_temp.source_ref() returns jsonb language sql as $$ select jsonb_build_object('platform','vinted','workspaceId',workspace_id,'connectionId',connection_id,'externalId',external_id,'entryId',id,'fingerprint',encode(extensions.digest(((body->'transferSource')-'observedAt')::text,'sha256'),'hex')) from public.marketplace_account_entries where id='51000000-0000-4000-8000-000000000031'; $$;
create function pg_temp.create_draft(p_source jsonb default pg_temp.source_ref(),p_request uuid default '51000000-0000-4000-8000-000000000041') returns jsonb language sql as $$ select public.kleinanzeigen_create_transfer_draft('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),p_source,'{"title":"Jacke","description":"Vollständiger Text","priceCents":1200,"currency":"EUR","priceType":"FIXED","shippingType":"pickup","postalCode":null,"categoryId":null,"categoryFields":{},"schemaRevision":null}',p_request); $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"51000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select pg_temp.create_draft()$$,'Testentwurf angelegt');

select throws_ok($$select public.kleinanzeigen_complete_transfer_images('51000000-0000-4000-8000-000000000011',pg_temp.draft_id(),1,'51000000-0000-4000-8000-000000000001','[]')$$,'42501',null,'Bildabschluss ist servergebunden');
reset role;
create function pg_temp.complete_images(p_revision bigint default 1) returns jsonb language sql security definer as $$select public.kleinanzeigen_complete_transfer_images('51000000-0000-4000-8000-000000000011',pg_temp.draft_id(),p_revision,'51000000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_build_object('storagePath','listings/51000000-0000-4000-8000-000000000011/'||(select id::text from public.listings)||'/0.jpg','fileName','Vinted-1.jpg','sortOrder',0)));$$;
set local role service_role;
select throws_ok($$select pg_temp.complete_images()$$,'22023',null,'Fehlende private Datei blockiert die Vollständigkeit');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'item-media','listings/51000000-0000-4000-8000-000000000011/'||id::text||'/0.jpg','{"mimetype":"image/jpeg","size":1024}'::jsonb from public.listings;
set local role service_role;
select lives_ok($$select pg_temp.complete_images()$$,'Alle Fotos werden atomar übernommen');
reset role;

reset role;
update public.kleinanzeigen_connections set status='connected',quota_used=99,quota_observed_at=clock_timestamp() where external_account_id='88';
insert into public.kleinanzeigen_local_grants(workspace_id,connection_id,approved_by,installation_id,token_hash,grant_generation,expires_at,can_publish) select workspace_id,id,created_by,'51000000-0000-4000-8000-000000000051',repeat('a',64),2,clock_timestamp()+interval '1 hour',true from public.kleinanzeigen_connections where external_account_id='88';
insert into public.kleinanzeigen_form_schemas(workspace_id,connection_id,category_path,schema_revision,provider_schema,grant_generation,observed_at) select workspace_id,id,'153/160/shirts',repeat('a',64),'{"categoryPath":"153/160/shirts","categoryLabel":"Shirts","titleMax":65,"descriptionMax":4000,"photoCountMax":20,"photoBytesMax":12582912,"priceStepCents":100,"fields":[{"key":"kleidung_herren.condition","label":"Zustand","kind":"select","selection":"value","required":false,"choices":[{"value":"ok","label":"Gut","description":""}]}],"shipping":{"defaultGroup":null,"defaultMethods":[],"groups":[]}}',2,clock_timestamp() from public.kleinanzeigen_connections where external_account_id='88';
update public.listings set category_id='153/160/shirts',category_fields='{"kleidung_herren.condition":"ok"}',schema_revision=repeat('a',64),postal_code='12345';
insert into storage.objects(bucket_id,name,metadata) select 'item-media','kleinanzeigen-jobs/51000000-0000-4000-8000-000000000011/51000000-0000-4000-8000-000000000061/51000000-0000-4000-8000-000000000062/'||id::text||'.jpg','{"mimetype":"image/jpeg","size":1024}'::jsonb from public.listing_images;
create function pg_temp.job_photos() returns jsonb language sql security definer as $$select jsonb_agg(jsonb_build_object('imageId',id,'storagePath','kleinanzeigen-jobs/51000000-0000-4000-8000-000000000011/51000000-0000-4000-8000-000000000061/51000000-0000-4000-8000-000000000062/'||id::text||'.jpg','fileName','Bild.jpg','mimeType','image/jpeg','byteSize',1024,'sha256',repeat('b',64))) from public.listing_images;$$;
create function pg_temp.enqueue(p_revision bigint default 4,p_request uuid default '51000000-0000-4000-8000-000000000061',p_user uuid default '51000000-0000-4000-8000-000000000001',p_photos jsonb default pg_temp.job_photos()) returns jsonb language sql security definer as $$select public.kleinanzeigen_enqueue_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),pg_temp.draft_id(),p_revision,p_request,p_user,p_photos);$$;
set local role service_role;
select pg_temp.enqueue();reset role;
create function pg_temp.claim(p_claim text default repeat('c',64)) returns jsonb language sql security definer as $$select public.kleinanzeigen_claim_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),p_claim);$$;
create function pg_temp.begin_job(p_fee jsonb default jsonb_build_object('state','free','observedAt',clock_timestamp()),p_version bigint default null) returns jsonb language sql security definer as $$select public.kleinanzeigen_begin_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64),coalesce(p_version,(select version from public.kleinanzeigen_publication_jobs)),p_fee);$$;
create function pg_temp.result(p_outcome text default 'confirmed',p_account text default '88',p_external_id text default '999') returns jsonb language sql as $$select jsonb_build_object('outcome',p_outcome,'externalAccountId',p_account,'externalId',p_external_id,'providerState',case when p_outcome='processing' then 'processing' else 'active' end,'verifiedAt',clock_timestamp(),'url','https://www.kleinanzeigen.de/s-anzeige/jacke/'||p_external_id||'-160-1');$$;
create function pg_temp.finish_job(p_result jsonb default pg_temp.result()) returns jsonb language sql security definer as $$select public.kleinanzeigen_finish_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64),p_result);$$;
set local role service_role;
select is(pg_temp.claim()->>'state','claimed','Genau ein Versuch übernimmt den Auftrag');
select is(pg_temp.claim()->>'version','2','Gleiche Versuchkennung wiederholt einen verlorenen Claim ohne neuen Versuch');
select throws_ok($$select pg_temp.claim(repeat('d',64))$$,'40001',null,'Zweiter Browser erhält keinen parallelen Versuch');
select is(public.kleinanzeigen_listing_job_photo('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64),pg_temp.image_id())->'image'->>'imageId',(select id::text from public.listing_images),'Bildabruf bleibt beim beanspruchten Foto');
select throws_ok($$select public.kleinanzeigen_listing_job_photo('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64),'51000000-0000-4000-8000-000000000099')$$,'42501',null,'Fremde Bildkennung wird nicht geladen');
select is(public.kleinanzeigen_store_quota_observation('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,jsonb_build_object('externalAccountId','88','accountType','private','used',99,'observedAt',clock_timestamp(),'source','account_settings'),(select id from public.kleinanzeigen_publication_jobs))->'quota'->>'allowed','true','Aktuelle eigene Vormerkung wird bei der hundertsten Anzeige nicht doppelt gezählt');
select is(public.kleinanzeigen_read_draft_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),pg_temp.draft_id(),'51000000-0000-4000-8000-000000000001')->>'id',(select id::text from public.kleinanzeigen_publication_jobs),'Erneut geöffneter Entwurf findet seinen ursprünglichen Auftrag');
select throws_ok($$select pg_temp.begin_job(p_version=>1)$$,'40001',null,'Veraltete Version kann nicht beginnen');
reset role;update public.kleinanzeigen_publication_jobs set lease_until=clock_timestamp()-interval '1 second';set local role service_role;
select is(pg_temp.claim()->>'state','claimed','Abgelaufener Versuch vor begin darf neu beansprucht werden');
select is(pg_temp.begin_job()->>'authorized','true','Kostenloser geprüfter Auftrag beginnt genau einmal');
select is(pg_temp.begin_job()->>'authorized','false','Nach begin wird kein zweiter verbindlicher Klick freigegeben');
reset role;
create temporary table writing_guard_before as select version,lease_until from public.kleinanzeigen_publication_jobs;
set local role service_role;
select is(public.kleinanzeigen_check_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64))->>'active','true','Nach begin bleibt derselbe gültige Versuch vor dem einen Klick prüfbar');
reset role;
select is((select version from public.kleinanzeigen_publication_jobs),(select version from writing_guard_before),'Die Prüfung eines begonnenen Versuchs verändert seine Version nicht');
select is((select lease_until from public.kleinanzeigen_publication_jobs),(select lease_until from writing_guard_before),'Die Prüfung eines begonnenen Versuchs verlängert seine Lease nicht');
update public.kleinanzeigen_local_grants set revoked_at=clock_timestamp();
set local role service_role;
select throws_ok($$select public.kleinanzeigen_check_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64))$$,'42501',null,'Widerruf unmittelbar nach begin sperrt den letzten Klick');
reset role;update public.kleinanzeigen_local_grants set revoked_at=null;set local role service_role;

reset role;
select throws_ok($$update public.listings set title='Späte Änderung'$$,'55000',null,'Inhalt ist während writing gesperrt');
select throws_ok($$update public.listing_images set sort_order=2$$,'55000',null,'Auch Bilder und Reihenfolge sind während writing gesperrt');
update public.kleinanzeigen_publication_jobs set lease_until=clock_timestamp()-interval '1 second';set local role service_role;
select is(public.kleinanzeigen_check_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),repeat('a',64),2,(select id from public.kleinanzeigen_publication_jobs),repeat('c',64))->>'active','false','Abgelaufener begonnener Versuch erhält keine erneute Klickfreigabe');
select is(public.kleinanzeigen_read_listing_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),(select id from public.kleinanzeigen_publication_jobs),'51000000-0000-4000-8000-000000000001')->>'state','outcome_unknown','Neustart nach begin führt nur zum unbekannten Ergebnis');
select throws_ok($$select pg_temp.claim(repeat('d',64))$$,'40001',null,'Unbekannter Ausgang darf keinen neuen Schreibversuch bekommen');
select is(pg_temp.claim()->>'state','outcome_unknown','Ursprünglicher Versuch kann ausschließlich zum Abgleichen wiederaufgenommen werden');
select throws_ok($$select pg_temp.finish_job(pg_temp.result(p_external_id=>null))$$,'22023',null,'Ohne Ziel-ID keine Bestätigung');
select throws_ok($$select pg_temp.finish_job(pg_temp.result(p_account=>'89'))$$,'22023',null,'Anderes Konto kann keinen Erfolg bestätigen');
select is(pg_temp.finish_job()->>'state','confirmed','Aktive Ziel-ID wird bestätigt');
reset role;
select is((select status from public.listings),'online','Entwurf und Bestätigung werden gemeinsam gespeichert');
select is((select external_id from public.kleinanzeigen_publications),'999','Genau dieselbe Ziel-ID erscheint in der Lesekopie');
select is((select state from public.kleinanzeigen_publications),'active','Lesekopie ist erst nach geprüftem Ergebnis aktiv');
select is(public.kleinanzeigen_quota_capacity('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections))->>'reserved','1','Veröffentlichung bleibt bei noch unverändertem offiziellen Zähler vorgemerkt');
select throws_ok($$update public.kleinanzeigen_publication_jobs set immutable_snapshot='{}'$$,'22023',null,'Der angenommene Inhalt kann auch serverseitig nicht ausgetauscht werden');
create function pg_temp.reset_job() returns void language plpgsql security definer as $$begin delete from public.kleinanzeigen_publication_jobs;update public.listings set status='prepared',online_since=null;update public.kleinanzeigen_connections set quota_used=0,quota_observed_at=clock_timestamp();perform pg_temp.enqueue(p_revision=>(select revision from public.listings));end;$$;
select pg_temp.reset_job();set local role service_role;select pg_temp.claim();
select is(pg_temp.begin_job(jsonb_build_object('state','paid','observedAt',clock_timestamp()))->>'authorized','false','Gebühren verhindern begin unabhängig vom freien Zähler');
reset role;select is((select state from public.kleinanzeigen_publication_jobs),'needs_user_action','Gebührenstopp bleibt sichtbar und gibt keinen Klick frei');
select ok((select started_at is null from public.kleinanzeigen_publication_jobs),'Bei Gebühren wurde kein Schreibbeginn gespeichert');
select pg_temp.reset_job();set local role service_role;select pg_temp.claim();
select is(pg_temp.begin_job(jsonb_build_object('state','unknown','observedAt',clock_timestamp()))->>'authorized','false','Unbekannter Gebührenstand verhindert begin');
reset role;select pg_temp.reset_job();set local role service_role;select pg_temp.claim();
select is(pg_temp.begin_job(jsonb_build_object('state','free','observedAt',clock_timestamp()-interval '11 seconds'))->>'authorized','false','Veraltetes kostenloses Formular verhindert begin');
reset role;select pg_temp.reset_job();set local role service_role;select pg_temp.claim();select pg_temp.begin_job();
select is(pg_temp.finish_job(pg_temp.result('processing','88','777'))->>'state','writing','Verarbeitung bleibt ein begonnener Auftrag');
reset role;select is((select state from public.kleinanzeigen_publications where external_id='777'),'processing','Lesekopie behauptet während Verarbeitung keinen aktiven Anbieterstatus');
update public.kleinanzeigen_local_grants set revoked_at=clock_timestamp();
set local role service_role;
select set_config('test.ka.confirmed_result',pg_temp.result('confirmed','88','777')::text,true);
select is(pg_temp.finish_job(current_setting('test.ka.confirmed_result')::jsonb)->>'state','confirmed','Alter begonnener Versuch kann auch nach Widerruf eindeutig abgeschlossen werden');
select is(pg_temp.finish_job(current_setting('test.ka.confirmed_result')::jsonb)->>'state','confirmed','Verlorene finish-Antwort wird ohne zweiten Submit wiederholt');
reset role;
select is((select listed_count from public.listings),2,'Wiederholter Abschluss zählt die Veröffentlichung nicht doppelt');
select ok((select online_since is null from public.listings),'Ohne Anbieterzeit wird kein Veröffentlichungsdatum erfunden');
-- Nur Testtransaktion: Storage-API-internen Löschpfad nachbilden und dessen RLS prüfen.
select set_config('storage.allow_delete_query','true',true);
set local role authenticated;
with removed as (delete from storage.objects where name like 'kleinanzeigen-jobs/%' returning id) select is((select count(*)::integer from removed),0,'Nutzer kann unveränderliche Auftragsfotos nicht löschen');
reset role;
select * from finish();rollback;
